#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyTypeClass {
    IntegerType,
    FloatingType,
    ComplexType,
    BooleanType,
    ScalarType,
    NumberType,
    InexactType,
    Int8Type,
    Int16Type,
    Int32Type,
    Int64Type,
    UInt8Type,
    UInt16Type,
    UInt32Type,
    UInt64Type,
    Float32Type,
    Float64Type,
    Complex64Type,
    Complex128Type,
    ObjectType,
}

pub fn issubclass_(arg1: NumpyTypeClass, arg2: NumpyTypeClass) -> bool {
    // Reflexivity
    if arg1 == arg2 {
        return true;
    }

    use NumpyTypeClass::*;
    match (arg1, arg2) {
        // Integer leaves
        (Int8Type, IntegerType)
        | (Int16Type, IntegerType)
        | (Int32Type, IntegerType)
        | (Int64Type, IntegerType)
        | (UInt8Type, IntegerType)
        | (UInt16Type, IntegerType)
        | (UInt32Type, IntegerType)
        | (UInt64Type, IntegerType) => true,

        // Floating-point leaves
        (Float32Type, FloatingType) | (Float64Type, FloatingType) => true,

        // Complex leaves
        (Complex64Type, ComplexType) | (Complex128Type, ComplexType) => true,

        // Mid-level relations
        (IntegerType, NumberType)
        | (FloatingType, InexactType)
        | (FloatingType, NumberType)
        | (ComplexType, InexactType)
        | (ComplexType, NumberType) => true,

        // Top-level scalar relations
        (NumberType, ScalarType)
        | (BooleanType, ScalarType)
        | (IntegerType, ScalarType)
        | (FloatingType, ScalarType)
        | (ComplexType, ScalarType)
        | (InexactType, ScalarType) => true,

        // All other pairs are not direct subclasses
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_reflexivity() {
        for &ty in &[
            NumpyTypeClass::IntegerType,
            NumpyTypeClass::Int32Type,
            NumpyTypeClass::Float64Type,
            NumpyTypeClass::ObjectType,
        ] {
            assert!(issubclass_(ty, ty));
        }
    }

    #[test]
    fn test_integer_leaves() {
        assert!(issubclass_(NumpyTypeClass::Int8Type, NumpyTypeClass::IntegerType));
        assert!(issubclass_(NumpyTypeClass::UInt64Type, NumpyTypeClass::IntegerType));
        assert!(!issubclass_(NumpyTypeClass::Int8Type, NumpyTypeClass::NumberType)); // no transitivity
    }

    #[test]
    fn test_floating_leaves() {
        assert!(issubclass_(NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType));
        assert!(!issubclass_(NumpyTypeClass::Float32Type, NumpyTypeClass::InexactType)); // no transitivity
    }

    #[test]
    fn test_complex_leaves() {
        assert!(issubclass_(NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType));
        assert!(!issubclass_(NumpyTypeClass::Complex64Type, NumpyTypeClass::NumberType)); // no transitivity
    }

    #[test]
    fn test_mid_level_and_top_level() {
        assert!(issubclass_(NumpyTypeClass::IntegerType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType));
        assert!(issubclass_(NumpyTypeClass::ComplexType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::NumberType, NumpyTypeClass::ScalarType));
        assert!(issubclass_(NumpyTypeClass::BooleanType, NumpyTypeClass::ScalarType));
        assert!(!issubclass_(NumpyTypeClass::NumberType, NumpyTypeClass::NumberType)); // reflexive but already covered
    }

    #[test]
    fn test_object_type() {
        // ObjectType has no subclass relations except itself
        assert!(issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ObjectType));
        assert!(!issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ScalarType));
        assert!(!issubclass_(NumpyTypeClass::Int8Type, NumpyTypeClass::ObjectType));
    }
}